#include <vector>
#include <algorithm>
#include <utility>

std::vector<std::pair<int, int>> free_slots(int limit, std::vector<std::pair<int, int>> busy) {
    if (limit <= 0) return {};

    std::vector<std::pair<int, int>> free;
    for (const auto& interval : busy) {
        if (interval.first < 0 || interval.second > limit || interval.first >= interval.second) continue;
        if (free.empty() || free.back().second < interval.first) free.push_back(interval);
        else free.back().second = std::max(free.back().second, interval.second);
    }

    std::vector<std::pair<int, int>> merged;
    for (const auto& interval : free) {
        if (merged.empty() || merged.back().second < interval.first) merged.push_back(interval);
        else merged.back().second = std::max(merged.back().second, interval.second);
    }

    return merged;
}

To solve this problem, we can use a sliding window approach. The idea is to maintain a window that sums up to at least the threshold and find the shortest such window. Here's the C++20 source code implementing the `shortest_span` function:

```cpp
#include <vector>
#include <algorithm>
#include <numeric>

int shortest_span(const std::vector<int>& values, long long threshold) {
    int left = 0, right = 0;
    long long current_sum = 0;
    int min_length = std::numeric_limits<int>::max();

    while (right < values.size()) {
        current_sum += values[right];
        while (current_sum >= threshold) {
            min_length = std::min(min_length, right - left + 1);
            current_sum -= values[left];
            left++;
        }
        right++;
    }

    return min_length == std::numeric_limits<int>::max() ? 0 : min_length;
}
```

### Explanation:
1. **Initialization**:
   - `left` and `right` pointers are used to define the current window.
   - `current_sum` keeps track of the sum of the current window.
   - `min_length` is initialized to the maximum possible integer value to ensure any valid window will be shorter.

2. **Sliding Window**:
   - The `right` pointer moves to the right, adding the current value to `current_sum`.
   - If `current_sum` is greater than or equal to the threshold, the window is adjusted by moving the `left` pointer to the right and subtracting the value at the `left` pointer from `current_sum`.
   - This process continues until the window is no longer valid (i.e., `current_sum < threshold`).

3. **Update Minimum Length**:
   - If a valid window is found, update `min_length` if the current window is shorter.

4. **Return Result**:
   - If no valid window is found, return 0.
   - Otherwise, return the minimum length of the valid window.

This approach ensures that we find the shortest nonempty contiguous span of positive integers whose sum is at least the threshold in linear time.

#include <vector>
#include <unordered_map>
#include <queue>
#include <algorithm>

std::vector<std::vector<int>> build_layers(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<std::vector<int>> layers;
    std::unordered_map<int, std::vector<int>> graph;
    std::unordered_map<int, int> in_degree;
    std::queue<int> q;

    // Build the graph and in-degree map
    for (const auto& p : prerequisites) {
        graph[p.first].push_back(p.second);
        in_degree[p.second]++;
    }

    // Find all nodes with in-degree 0
    for (int i = 0; i < n; ++i) {
        if (in_degree[i] == 0) {
            q.push(i);
        }
    }

    // Perform topological sort
    while (!q.empty()) {
        int current = q.front();
        q.pop();
        layers.push_back({current});

        for (int neighbor : graph[current]) {
            in_degree[neighbor]--;
            if (in_degree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    // Check if there are any remaining nodes with in-degree 0
    if (!q.empty()) {
        return {};
    }

    return layers;
}

#include <vector>
#include <string>
#include <algorithm>
#include <unordered_map>
#include <cassert>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    if (k <= 0) return {};

    std::unordered_map<std::string, int> word_counts;
    for (const auto& word : words) {
        ++word_counts[word];
    }

    std::vector<std::pair<std::string, int>> sorted_words(word_counts.begin(), word_counts.end());
    std::sort(sorted_words.begin(), sorted_words.end(), [](const auto& a, const auto& b) {
        return a.second == b.second ? a.first < b.first : a.second > b.second;
    });

    std::vector<std::string> result;
    for (int i = 0; i < std::min(k, static_cast<int>(sorted_words.size())); ++i) {
        result.push_back(sorted_words[i].first);
    }

    return result;
}

int main() {
    assert(top_words({}, 3) == std::vector<std::string>());
    assert(top_words({"apple", "banana", "apple", "orange", "banana", "apple"}, 2) == std::vector<std::string>{"apple", "banana"});
    assert(top_words({"hello", "world", "hello", "cpp", "world", "cpp"}, 3) == std::vector<std::string>{"cpp", "hello", "world"});
    assert(top_words({"a", "b", "c", "d", "e"}, 1) == std::vector<std::string>{"a"});
    assert(top_words({"a", "a", "a", "a", "a"}, 3) == std::vector<std::string>{"a"});

    return 0;
}

#include <iostream>
#include <string>
#include <unordered_map>
#include <cassert>

int main() {
    std::unordered_map<std::string, int> inventory;
    std::string command;

    while (std::getline(std::cin, command)) {
        if (command == "PUT name") {
            std::string name;
            std::cin >> name;
            assert(!inventory.count(name));
            inventory[name] = 1;
        } else if (command == "TAKE name") {
            std::string name;
            std::cin >> name;
            assert(inventory.count(name));
            if (inventory[name] > 0) {
                inventory[name]--;
            }
        } else if (command == "QUERY name") {
            std::string name;
            std::cin >> name;
            assert(inventory.count(name));
            std::cout << inventory[name] << std::endl;
        } else {
            std::cerr << "Invalid command: " << command << std::endl;
        }
    }

    return 0;
}

